('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00168','Article R. 434-7 — Protection fonctionnelle',168,'string','Il l''assiste et l''accompagne dans les démarches relatives à sa défense.','Il l''assiste et l''accompagne dans les démarches relatives à sa défense.','{}'::jsonb,true),
