('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00190','Commentaire — R. 434-8',190,'string','Il est donc interdit au policier ou au gendarme de communiquer aux personnes non autorisées ou non habilitées, y compris au sein même des institutions, toute information ou renseignement ','Il est donc interdit au policier ou au gendarme de communiquer aux personnes non autorisées ou non habilitées, y compris au sein même des institutions, toute information ou renseignement ','{}'::jsonb,true),
