('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00224','Article R. 434-10 — Discernement',224,'title','Article R. 434-10','Article R. 434-10','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00225','Article R. 434-10 — Discernement',225,'string',' — Discernement

',' — Discernement

','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00226','Article R. 434-10 — Discernement',226,'string','Le policier ou le gendarme fait, dans l''exercice de ses fonctions, preuve de discernement.
','Le policier ou le gendarme fait, dans l''exercice de ses fonctions, preuve de discernement.
','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00227','Article R. 434-10 — Discernement',227,'string','Il tient compte en toutes circonstances de la nature des risques et menaces de chaque situation à laquelle il est confronté et des délais qu''il a pour agir, ','Il tient compte en toutes circonstances de la nature des risques et menaces de chaque situation à laquelle il est confronté et des délais qu''il a pour agir, ','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00228','Article R. 434-10 — Discernement',228,'string','pour choisir la meilleure réponse légale à lui apporter.','pour choisir la meilleure réponse légale à lui apporter.','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00229','Commentaire — R. 434-10',229,'title','Commentaire — R. 434-10','Commentaire — R. 434-10','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00230','Commentaire — R. 434-10',230,'_Paragraph','Dans l''exercice de ses missions, le policier ou le gendarme doit avant toute action procéder à une analyse de la situation et adapter son comportement en fonction ','Dans l''exercice de ses missions, le policier ou le gendarme doit avant toute action procéder à une analyse de la situation et adapter son comportement en fonction ','{}'::jsonb,true),
