','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00235','Commentaire — R. 434-10',235,'string','Pour autant, il doit faire preuve de bon sens et avoir l''intelligence des situations en graduant son action selon différents paramètres (danger, sécurité de soi-même ou d''autrui, ','Pour autant, il doit faire preuve de bon sens et avoir l''intelligence des situations en graduant son action selon différents paramètres (danger, sécurité de soi-même ou d''autrui, ','{}'::jsonb,true),
