','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00237','Commentaire — R. 434-10',237,'string','Enfin, le policier et le gendarme doivent appréhender chaque situation de façon différenciée afin d''éviter toute routine qui nuit souvent à la qualité du service rendu, ','Enfin, le policier et le gendarme doivent appréhender chaque situation de façon différenciée afin d''éviter toute routine qui nuit souvent à la qualité du service rendu, ','{}'::jsonb,true),
