('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00254','Article R. 434-11 — Impartialité',254,'string','Le policier et le gendarme accomplissent leurs missions en toute impartialité.
','Le policier et le gendarme accomplissent leurs missions en toute impartialité.
','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00255','Article R. 434-11 — Impartialité',255,'string','Ils accordent la même attention et le même respect à toute personne et n''établissent aucune distinction dans leurs actes et leurs propos de nature à constituer l''une des discriminations ','Ils accordent la même attention et le même respect à toute personne et n''établissent aucune distinction dans leurs actes et leurs propos de nature à constituer l''une des discriminations ','{}'::jsonb,true),
