('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00266','Commentaire — R. 434-11',266,'TextSpan','Code pénal, ','Code pénal, ','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00267','Commentaire — R. 434-11',267,'TextSpan','article 225-1','article 225-1','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00268','Commentaire — R. 434-11',268,'TextSpan',' : « Constitue une discrimination toute distinction opérée entre les personnes physiques à raison de leur origine, de leur sexe, de leur situation de famille, de leur grossesse, de leur apparence physique, de leur patronyme, de leur état de santé, de leur handicap, de leurs caractéristiques génétiques, de leurs mœurs, de leur orientation ou identité sexuelle, de leur âge, de leurs opinions politiques, de leurs activités syndicales, de leur appartenance ou de leur non-appartenance, vraie ou supposée, à une ethnie, une nation, une race ou une religion déterminée. Constitue également une discrimination toute distinction opérée entre les personnes morales à raison de l''origine, du sexe, de la situation de famille, de l''apparence physique, du patronyme, de l''état de santé, du handicap, des caractéristiques génétiques, des moeurs, de l''orientation ou identité sexuelle, de l''âge, des opinions politiques, des activités syndicales, de l''appartenance ou de la non-appartenance, vraie ou supposée, à une ethnie, une nation, une race ou une religion déterminée des membres ou de certains membres de ces personnes morales. »',' : « Constitue une discrimination toute distinction opérée entre les personnes physiques à raison de leur origine, de leur sexe, de leur situation de famille, de leur grossesse, de leur apparence physique, de leur patronyme, de leur état de santé, de leur handicap, de leurs caractéristiques génétiques, de leurs mœurs, de leur orientation ou identité sexuelle, de leur âge, de leurs opinions politiques, de leurs activités syndicales, de leur appartenance ou de leur non-appartenance, vraie ou supposée, à une ethnie, une nation, une race ou une religion déterminée. Constitue également une discrimination toute distinction opérée entre les personnes morales à raison de l''origine, du sexe, de la situation de famille, de l''apparence physique, du patronyme, de l''état de santé, du handicap, des caractéristiques génétiques, des moeurs, de l''orientation ou identité sexuelle, de l''âge, des opinions politiques, des activités syndicales, de l''appartenance ou de la non-appartenance, vraie ou supposée, à une ethnie, une nation, une race ou une religion déterminée des membres ou de certains membres de ces personnes morales. »','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00269','Commentaire — R. 434-11',269,'_Paragraph','• ciblage positif ou négatif d''une personne ou d''un groupe de personnes (victime ou mis en cause) en raison de ses opinions religieuses, philosophiques, politiques, de son orientation sexuelle, etc.;
