('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00276','Article R. 434-12 — Crédit et renom',276,'string',' — Crédit et renom de la police nationale et de la gendarmerie nationale

',' — Crédit et renom de la police nationale et de la gendarmerie nationale

','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00277','Article R. 434-12 — Crédit et renom',277,'string','Le policier ou le gendarme ne se départ de sa dignité en aucune circonstance.

