('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00464','Article R. 434-21 — Données à caractère personnel',464,'string','Article R. 434-21','Article R. 434-21','{}'::jsonb,true),
('lib/content/gpx_scolarite/institutions_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00465','Article R. 434-21 — Données à caractère personnel',465,'string',' — Usage des traitements de données à caractère personnel

